#!/usr/bin/env python3
"""Apply recovered PC-only changes after the five pinned console patches.

Exact anchors must occur once. Never writes to the CARTDECK checkout.
"""
import json
from pathlib import Path
import sys

EDITS = json.loads(r'''{"input.h":[["        std::unordered_set<int> pressedKeys;","        std::unordered_set<int> pressedKeys;\n        std::unordered_set<int> pcKeys;\n        bool mouseButtons[3] = {};\n        int pendingX = 0, pendingY = 0, mouseX = 0, mouseY = 0;"],["    int16_t getInputState(unsigned port, unsigned device, unsigned index, unsigned id);","    static constexpr int PC_KEY_BASE = 10000;\n    static constexpr int PC_MOUSE_BUTTON_BASE = 10600;\n    static constexpr int PC_CLEAR = 10610;\n    static constexpr int PC_MOUSE_SOURCE = 5;\n\n    int16_t getInputState(unsigned port, unsigned device, unsigned index, unsigned id);\n    void pollPcInput();\n    void clearPcInput(unsigned port);"]],"input.cpp":[["        case RETRO_DEVICE_POINTER: {","        case RETRO_DEVICE_KEYBOARD:\n            return pads[port].pcKeys.count(static_cast<int>(id)) != 0;\n        case RETRO_DEVICE_MOUSE:\n            switch (id) {\n                case RETRO_DEVICE_ID_MOUSE_X: return static_cast<int16_t>(pads[port].mouseX);\n                case RETRO_DEVICE_ID_MOUSE_Y: return static_cast<int16_t>(pads[port].mouseY);\n                case RETRO_DEVICE_ID_MOUSE_LEFT: return pads[port].mouseButtons[0];\n                case RETRO_DEVICE_ID_MOUSE_RIGHT: return pads[port].mouseButtons[1];\n                case RETRO_DEVICE_ID_MOUSE_MIDDLE: return pads[port].mouseButtons[2];\n                default: return 0;\n            }\n\n        case RETRO_DEVICE_POINTER: {"],["    int retroKeyCode = convertAndroidToLibretroKey(keyCode);","    if (keyCode == PC_CLEAR) {\n        clearPcInput(port);\n        return;\n    }\n    if (keyCode >= PC_KEY_BASE && keyCode < PC_KEY_BASE + RETROK_LAST) {\n        if (action == AKEY_EVENT_ACTION_DOWN) pads[port].pcKeys.insert(keyCode - PC_KEY_BASE);\n        else if (action == AKEY_EVENT_ACTION_UP) pads[port].pcKeys.erase(keyCode - PC_KEY_BASE);\n        return;\n    }\n    if (keyCode >= PC_MOUSE_BUTTON_BASE && keyCode < PC_MOUSE_BUTTON_BASE + 3) {\n        if (action == AKEY_EVENT_ACTION_DOWN || action == AKEY_EVENT_ACTION_UP)\n            pads[port].mouseButtons[keyCode - PC_MOUSE_BUTTON_BASE] = action == AKEY_EVENT_ACTION_DOWN;\n        return;\n    }\n    int retroKeyCode = convertAndroidToLibretroKey(keyCode);"],["            pads[port].pointerScreenYAxis = yAxis;\n            break;","            pads[port].pointerScreenYAxis = yAxis;\n            break;\n\n        case Input::PC_MOUSE_SOURCE: {\n            auto delta = [](float v) {\n                return std::isfinite(v) ? static_cast<int>(std::clamp(v, -32767.f, 32767.f)) : 0;\n            };\n            pads[port].pendingX = std::clamp(pads[port].pendingX + delta(xAxis), -32767, 32767);\n            pads[port].pendingY = std::clamp(pads[port].pendingY + delta(yAxis), -32767, 32767);\n            break;\n        }"],["template<typename... T>","void Input::pollPcInput() {\n    for (auto &pad : pads) {\n        pad.mouseX = pad.pendingX;\n        pad.mouseY = pad.pendingY;\n        pad.pendingX = pad.pendingY = 0;\n    }\n}\n\nvoid Input::clearPcInput(unsigned port) {\n    if (port >= 4) return;\n    auto &pad = pads[port];\n    pad.pcKeys.clear();\n    for (auto &button : pad.mouseButtons) button = false;\n    pad.mouseX = pad.mouseY = pad.pendingX = pad.pendingY = 0;\n}\n\ntemplate<typename... T>"]],"environment.h":[["    struct retro_disk_control_callback* getRetroDiskControlCallback() const;","    struct retro_disk_control_callback* getRetroDiskControlCallback() const;\n    retro_keyboard_event_t getKeyboardCallback() const { return keyboardCallback; }"],["    struct retro_disk_control_callback *retro_disk_control_callback = nullptr;","    struct retro_disk_control_callback *retro_disk_control_callback = nullptr;\n    retro_keyboard_event_t keyboardCallback = nullptr;"]],"environment.cpp":[["    retro_disk_control_callback = nullptr;","    retro_disk_control_callback = nullptr;\n    keyboardCallback = nullptr;"],["        case RETRO_ENVIRONMENT_GET_CAN_DUPE:","        case RETRO_ENVIRONMENT_SET_KEYBOARD_CALLBACK:\n            keyboardCallback = data ? static_cast<retro_keyboard_callback*>(data)->callback : nullptr;\n            return true;\n\n        case RETRO_ENVIRONMENT_GET_CAN_DUPE:"]],"libretrodroid.cpp":[["void LibretroDroid::callback_retro_set_input_poll() {\n    // Do nothing in here...","void LibretroDroid::callback_retro_set_input_poll() {\n    auto &host = LibretroDroid::getInstance();\n    if (host.input) host.input->pollPcInput();"],["    if (input) {\n        input->onKeyEvent(port, action, keyCode);","    if (input && port < 4) {\n        auto callback = Environment::getInstance().getKeyboardCallback();\n        if (keyCode == Input::PC_CLEAR) {\n            if (callback) {\n                for (unsigned key = 0; key < RETROK_LAST; ++key)\n                    if (input->getInputState(port, RETRO_DEVICE_KEYBOARD, 0, key))\n                        callback(false, key, 0, 0);\n            }\n            input->clearPcInput(port);\n            return;\n        }\n        if (keyCode >= Input::PC_KEY_BASE && keyCode < Input::PC_KEY_BASE + RETROK_LAST) {\n            const unsigned key = keyCode - Input::PC_KEY_BASE;\n            const bool wasDown = input->getInputState(port, RETRO_DEVICE_KEYBOARD, 0, key) != 0;\n            input->onKeyEvent(port, action, keyCode);\n            const bool down = input->getInputState(port, RETRO_DEVICE_KEYBOARD, 0, key) != 0;\n            if (callback && down != wasDown) callback(down, key, 0, 0);\n            return;\n        }\n        input->onKeyEvent(port, action, keyCode);"]]}''')

def apply(root):
    cpp = root / "libretrodroid/src/main/cpp"
    updates = {}
    for name, edits in EDITS.items():
        path = cpp / name
        text = path.read_text()
        if any(after in text for before, after in edits):
            raise ValueError(f"PC overlay already present: {name}")
        for before, after in edits:
            if text.count(before) != 1:
                raise ValueError(f"PC overlay anchor mismatch: {name}: {before[:80]}")
            text = text.replace(before, after, 1)
        if name == "input.cpp" and "#include <algorithm>" not in text:
            text = text.replace("#include <cmath>", "#include <cmath>\n#include <algorithm>", 1)
        updates[path] = text
    for path, text in updates.items():
        path.write_text(text)

if __name__ == "__main__":
    apply(Path(sys.argv[1]).resolve())
